// src/pages/Finance.jsx
import React, { useState, useEffect } from 'react';
import { useClaim } from '../hooks/useClaim.js';
import { useAuth } from '../hooks/useAuth.js';
import { CLAIM_STATUS, CLAIM_STATUS_LABELS, CLAIM_STATUS_COLORS, CLAIM_TYPE } from '../constants/claimStatus.js';
import './Finance.css';

const Finance = () => {
  const { user } = useAuth();
  const { claims, verifyClaim, rejectClaim, getReadyVerifyClaims } = useClaim();
  
  // ============================================================
  // STATE MANAGEMENT
  // ============================================================
  
  // Filter states
  const [filterType, setFilterType] = useState('all'); // 'all', 'replacement', 'repair', 'excess'
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  
  // Pagination states
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);
  
  // Selected claim for screenshot view
  const [selectedClaim, setSelectedClaim] = useState(null);
  const [showScreenshotModal, setShowScreenshotModal] = useState(false);
  
  // Sort states
  const [sortField, setSortField] = useState('created_at');
  const [sortDirection, setSortDirection] = useState('desc');
  
  // Loading and export states
  const [isExporting, setIsExporting] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  
  // ============================================================
  // DATA FETCHING (Comment for backend integration)
  // ============================================================
  
  /*
    ============================================================
    BACKEND INTEGRATION NOTES:
    ============================================================
    
    1. Replace the claims array with API call:
       const response = await fetch('/api/claims/finance');
       const data = await response.json();
       setAllClaims(data);
    
    2. For filtering by date, use query parameters:
       const response = await fetch(
         `/api/claims/finance?startDate=${startDate}&endDate=${endDate}`
       );
    
    3. For filtering by type:
       const response = await fetch(
         `/api/claims/finance?type=${filterType}`
       );
    
    4. For pagination:
       const response = await fetch(
         `/api/claims/finance?page=${currentPage}&limit=${itemsPerPage}`
       );
    
    5. For searching:
       const response = await fetch(
         `/api/claims/finance?search=${searchTerm}`
       );
  */
  
  // Get all claims (simulated)
  const allClaims = claims || [];
  
  // ============================================================
  // FILTERING LOGIC
  // ============================================================
  
  /**
   * Filter claims based on type, date, status, and search term
   * This will be replaced by API filtering when backend is ready
   */
  const getFilteredClaims = () => {
    let filtered = [...allClaims];
    
    // Filter by claim type
    if (filterType === 'replacement') {
      filtered = filtered.filter(c => c.claim_type === CLAIM_TYPE.REPLACEMENT);
    } else if (filterType === 'repair') {
      filtered = filtered.filter(c => c.claim_type === CLAIM_TYPE.REPAIR);
    } else if (filterType === 'excess') {
      filtered = filtered.filter(c => c.claim_subtype === 'Excess');
    }
    
    // Filter by status
    if (statusFilter !== 'all') {
      filtered = filtered.filter(c => c.status === statusFilter);
    }
    
    // Filter by date range
    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(c => {
        const claimDate = new Date(c.created_at || c.insuranceClaimDate);
        return claimDate >= start;
      });
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59);
      filtered = filtered.filter(c => {
        const claimDate = new Date(c.created_at || c.insuranceClaimDate);
        return claimDate <= end;
      });
    }
    
    // Filter by search term (cover note or customer name)
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(c => 
        c.covernoteRefNumber?.toLowerCase().includes(term) ||
        c.customerName?.toLowerCase().includes(term) ||
        c.msisdn?.includes(term)
      );
    }
    
    // Sort
    filtered.sort((a, b) => {
      let aVal = a[sortField] || '';
      let bVal = b[sortField] || '';
      
      // Handle date strings
      if (sortField === 'created_at' || sortField === 'insuranceClaimDate' || sortField === 'transaction_date') {
        aVal = new Date(aVal).getTime() || 0;
        bVal = new Date(bVal).getTime() || 0;
      }
      
      // Handle numbers
      if (sortField === 'total_amount' || sortField === 'amount') {
        aVal = parseFloat(aVal) || 0;
        bVal = parseFloat(bVal) || 0;
      }
      
      if (aVal < bVal) return sortDirection === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });
    
    return filtered;
  };
  
  /**
   * Get latest claims (for finance dashboard)
   * In production, this would be an API call:
   * GET /api/claims/latest?limit=10
   */
  const getLatestClaims = (limit = 10) => {
    const sorted = [...allClaims].sort((a, b) => {
      const dateA = new Date(a.created_at || a.insuranceClaimDate);
      const dateB = new Date(b.created_at || b.insuranceClaimDate);
      return dateB - dateA;
    });
    return sorted.slice(0, limit);
  };
  
  /**
   * Get claims ready for verification
   * In production, this would be an API call:
   * GET /api/claims/ready-verify
   */
  const getReadyVerify = () => {
    return allClaims.filter(c => c.status === CLAIM_STATUS.READY_VERIFY);
  };
  
  // ============================================================
  // COMPUTED VALUES
  // ============================================================
  
  const filteredClaims = getFilteredClaims();
  const latestClaims = getLatestClaims(10);
  const readyVerify = getReadyVerify();
  
  // Pagination
  const totalPages = Math.ceil(filteredClaims.length / itemsPerPage);
  const paginatedClaims = filteredClaims.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );
  
  // Stats
  const stats = {
    total: allClaims.length,
    pending: allClaims.filter(c => c.status === CLAIM_STATUS.PENDING).length,
    readyVerify: readyVerify.length,
    verified: allClaims.filter(c => c.status === CLAIM_STATUS.VERIFIED).length,
    rejected: allClaims.filter(c => c.status === CLAIM_STATUS.REJECTED).length,
    replacement: allClaims.filter(c => c.claim_type === CLAIM_TYPE.REPLACEMENT).length,
    repair: allClaims.filter(c => c.claim_type === CLAIM_TYPE.REPAIR).length,
    excess: allClaims.filter(c => c.claim_subtype === 'Excess').length
  };
  
  // ============================================================
  // HANDLER FUNCTIONS
  // ============================================================
  
  /**
   * Handle verify claim
   * In production:
   * const response = await fetch(`/api/claims/${claimId}/verify`, {
   *   method: 'POST',
   *   headers: { 'Content-Type': 'application/json' },
   *   body: JSON.stringify({ verifiedBy: user.id })
   * });
   */
  const handleVerify = (claimId) => {
    if (window.confirm('Verify this transaction?')) {
      verifyClaim(claimId);
      alert('✅ Transaction verified successfully!');
    }
  };
  
  /**
   * Handle reject claim
   * In production:
   * const response = await fetch(`/api/claims/${claimId}/reject`, {
   *   method: 'POST',
   *   headers: { 'Content-Type': 'application/json' },
   *   body: JSON.stringify({ 
   *     rejectedBy: user.id,
   *     reason: prompt('Enter rejection reason:')
   *   })
   * });
   */
  const handleReject = (claimId) => {
    if (window.confirm('Reject this transaction?')) {
      rejectClaim(claimId);
      alert('❌ Transaction rejected.');
    }
  };
  
  /**
   * Handle view screenshot
   */
  const handleViewScreenshot = (claim) => {
    setSelectedClaim(claim);
    setShowScreenshotModal(true);
  };
  
  /**
   * Handle sort change
   */
  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };
  
  /**
   * Handle page change
   */
  const handlePageChange = (page) => {
    setCurrentPage(page);
    // Scroll to top of table
    document.querySelector('.finance-list')?.scrollIntoView({ behavior: 'smooth' });
  };
  
  /**
   * Handle export to CSV
   * In production:
   * const response = await fetch('/api/claims/export', {
   *   method: 'POST',
   *   headers: { 'Content-Type': 'application/json' },
   *   body: JSON.stringify({
   *     filters: { type: filterType, startDate, endDate, status: statusFilter },
   *     format: 'csv'
   *   })
   * });
   * const blob = await response.blob();
   * const url = window.URL.createObjectURL(blob);
   * const a = document.createElement('a');
   * a.href = url;
   * a.download = `claims_${new Date().toISOString().slice(0,10)}.csv`;
   * a.click();
   */
  const handleExportCSV = () => {
    setIsExporting(true);
    
    // Simulate export delay
    setTimeout(() => {
      try {
        // Get data to export (all filtered claims or selected based on current view)
        const dataToExport = filteredClaims.length > 0 ? filteredClaims : allClaims;
        
        // Define CSV headers
        const headers = [
          'Cover Note',
          'Customer',
          'Phone',
          'IMEI',
          'Model',
          'Type',
          'Subtype',
          'Status',
          'Amount',
          'Transaction ID',
          'Transaction Date',
          'Claim Date',
          'Program',
          'Agent'
        ];
        
        // Create CSV rows
        const rows = dataToExport.map(claim => [
          claim.covernoteRefNumber || 'N/A',
          claim.customerName || 'N/A',
          claim.msisdn || 'N/A',
          claim.imeiNumber || 'N/A',
          claim.model || 'N/A',
          claim.claim_type || 'N/A',
          claim.claim_subtype || 'N/A',
          CLAIM_STATUS_LABELS[claim.status] || claim.status || 'N/A',
          claim.total_amount ? `"${claim.total_amount.toLocaleString()}"` : 'N/A',
          claim.transaction_id || 'N/A',
          claim.transaction_date || 'N/A',
          claim.insuranceClaimDate || claim.created_at || 'N/A',
          claim.program || 'N/A',
          claim.representative || 'N/A'
        ]);
        
        // Combine headers and rows
        const csvContent = [
          headers.join(','),
          ...rows.map(row => row.join(','))
        ].join('\n');
        
        // Create download
        const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        link.href = url;
        link.download = `claims_export_${new Date().toISOString().slice(0,10)}.csv`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        
        alert('✅ CSV exported successfully!');
      } catch (error) {
        console.error('Export error:', error);
        alert('❌ Error exporting CSV. Please try again.');
      } finally {
        setIsExporting(false);
      }
    }, 1000);
  };
  
  /**
   * Handle export all claims
   */
  const handleExportAll = () => {
    if (window.confirm('Export all claims?')) {
      // Temporarily show all claims for export
      const currentFilter = filterType;
      const currentStatus = statusFilter;
      const currentStart = startDate;
      const currentEnd = endDate;
      
      // Reset filters for export
      setFilterType('all');
      setStatusFilter('all');
      setStartDate('');
      setEndDate('');
      
      // Export after state update
      setTimeout(() => {
        handleExportCSV();
        // Restore filters
        setFilterType(currentFilter);
        setStatusFilter(currentStatus);
        setStartDate(currentStart);
        setEndDate(currentEnd);
      }, 100);
    }
  };
  
  /**
   * Handle clear all filters
   */
  const handleClearFilters = () => {
    setFilterType('all');
    setStatusFilter('all');
    setStartDate('');
    setEndDate('');
    setSearchTerm('');
    setCurrentPage(1);
  };
  
  // ============================================================
  // RENDER HELPERS
  // ============================================================
  
  /**
   * Get status badge
   */
  const getStatusBadge = (status) => {
    return (
      <span className="status-badge" style={{ backgroundColor: CLAIM_STATUS_COLORS[status] }}>
        {CLAIM_STATUS_LABELS[status] || status}
      </span>
    );
  };
  
  /**
   * Get type badge
   */
  const getTypeBadge = (claim) => {
    const type = claim.claim_type || 'N/A';
    const subtype = claim.claim_subtype || '';
    const isExcess = subtype === 'Excess';
    const className = `type-badge ${type?.toLowerCase()} ${isExcess ? 'excess' : ''}`;
    return (
      <span className={className}>
        {type} {subtype && `· ${subtype}`}
      </span>
    );
  };
  
  /**
   * Format date
   */
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch {
      return dateString;
    }
  };
  
  /**
   * Format currency
   */
  const formatCurrency = (amount) => {
    if (!amount) return 'N/A';
    return `TZS ${amount.toLocaleString()}`;
  };
  
  // ============================================================
  // RENDER
  // ============================================================
  
  return (
    <div className="finance-page">
      {/* ============================================================
          HEADER
          ============================================================ */}
      <div className="finance-header">
        <div className="finance-header-content">
          <i className="fas fa-coins"></i>
          <h2>Finance Dashboard</h2>
          <span className="finance-subtitle">Verify and manage claims</span>
        </div>
        <div className="finance-actions">
          <button 
            className="btn-primary export-btn"
            onClick={handleExportCSV}
            disabled={isExporting}
          >
            {isExporting ? (
              <><i className="fas fa-spinner fa-spin"></i> Exporting...</>
            ) : (
              <><i className="fas fa-file-export"></i> Export Filtered</>
            )}
          </button>
          <button 
            className="btn-outline export-all-btn"
            onClick={handleExportAll}
            disabled={isExporting}
          >
            <i className="fas fa-download"></i> Export All
          </button>
        </div>
      </div>
      
      {/* ============================================================
          STATISTICS CARDS
          ============================================================ */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon total">
            <i className="fas fa-file-invoice"></i>
          </div>
          <div className="stat-number">{stats.total}</div>
          <div className="stat-label">Total Claims</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon ready">
            <i className="fas fa-check-double"></i>
          </div>
          <div className="stat-number">{stats.readyVerify}</div>
          <div className="stat-label">Ready to Verify</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon verified">
            <i className="fas fa-check-circle"></i>
          </div>
          <div className="stat-number">{stats.verified}</div>
          <div className="stat-label">Verified</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon rejected">
            <i className="fas fa-times-circle"></i>
          </div>
          <div className="stat-number">{stats.rejected}</div>
          <div className="stat-label">Rejected</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon replacement">
            <i className="fas fa-exchange-alt"></i>
          </div>
          <div className="stat-number">{stats.replacement}</div>
          <div className="stat-label">Replacement</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon repair">
            <i className="fas fa-tools"></i>
          </div>
          <div className="stat-number">{stats.repair}</div>
          <div className="stat-label">Repair</div>
        </div>
      </div>
      
      {/* ============================================================
          RECENT CLAIMS SECTION
          ============================================================ */}
      <div className="finance-section">
        <div className="section-header">
          <div className="section-title">
            <i className="fas fa-clock"></i>
            <h3>Recent Claims</h3>
            <span className="section-badge">Latest {latestClaims.length} claims</span>
          </div>
          <div className="section-actions">
            <button 
              className="btn-outline small"
              onClick={() => {
                setFilterType('all');
                setStatusFilter('all');
                setStartDate('');
                setEndDate('');
              }}
            >
              <i className="fas fa-sync"></i> Reset
            </button>
          </div>
        </div>
        <div className="recent-claims-list">
          {latestClaims.length === 0 ? (
            <div className="empty-state">
              <i className="fas fa-inbox"></i>
              <p>No recent claims found</p>
            </div>
          ) : (
            latestClaims.map(claim => (
              <div key={claim.id} className="recent-claim-item">
                <div className="recent-claim-info">
                  <span className="claim-ref">{claim.covernoteRefNumber}</span>
                  <span className="claim-customer">{claim.customerName}</span>
                  <span className="claim-date">{formatDate(claim.created_at || claim.insuranceClaimDate)}</span>
                </div>
                <div className="recent-claim-status">
                  {getStatusBadge(claim.status)}
                  <span className="claim-amount">{formatCurrency(claim.total_amount)}</span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
      
      {/* ============================================================
          FILTER SECTION
          ============================================================ */}
      <div className="finance-container">
        <div className="finance-filters">
          <div className="filter-group">
            <label>Claim Type</label>
            <select 
              className="filter-select"
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
            >
              <option value="all">All Types</option>
              <option value="replacement">Replacement</option>
              <option value="repair">Repair</option>
              <option value="excess">Excess</option>
            </select>
          </div>
          
          <div className="filter-group">
            <label>Status</label>
            <select 
              className="filter-select"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
            >
              <option value="all">All Status</option>
              <option value={CLAIM_STATUS.PENDING}>Pending</option>
              <option value={CLAIM_STATUS.READY_VERIFY}>Ready to Verify</option>
              <option value={CLAIM_STATUS.VERIFIED}>Verified</option>
              <option value={CLAIM_STATUS.REJECTED}>Rejected</option>
              <option value={CLAIM_STATUS.AWAITING_CARE}>Awaiting Care</option>
              <option value={CLAIM_STATUS.AWAITING_REP}>Awaiting Rep</option>
            </select>
          </div>
          
          <div className="filter-group">
            <label>Start Date</label>
            <input
              type="date"
              className="filter-input"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
          </div>
          
          <div className="filter-group">
            <label>End Date</label>
            <input
              type="date"
              className="filter-input"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
            />
          </div>
          
          <div className="filter-group search-group">
            <label>Search</label>
            <div className="search-box">
              <i className="fas fa-search"></i>
              <input
                type="text"
                placeholder="Search cover note, customer..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              {searchTerm && (
                <button className="clear-search" onClick={() => setSearchTerm('')}>
                  <i className="fas fa-times"></i>
                </button>
              )}
            </div>
          </div>
          
          <div className="filter-actions">
            <button className="btn-outline small" onClick={handleClearFilters}>
              <i className="fas fa-undo"></i> Clear
            </button>
          </div>
        </div>
        
        {/* ============================================================
            RESULTS SUMMARY
            ============================================================ */}
        <div className="results-summary">
          <span>
            Showing <strong>{paginatedClaims.length}</strong> of <strong>{filteredClaims.length}</strong> claims
            {filterType !== 'all' && ` · Type: ${filterType}`}
            {statusFilter !== 'all' && ` · Status: ${CLAIM_STATUS_LABELS[statusFilter] || statusFilter}`}
            {(startDate || endDate) && ' · Date filtered'}
          </span>
          <span className="results-actions">
            <button 
              className="btn-outline small"
              onClick={() => setItemsPerPage(prev => prev === 10 ? 25 : prev === 25 ? 50 : 10)}
            >
              Show {itemsPerPage}
            </button>
          </span>
        </div>
        
        {/* ============================================================
            CLAIMS TABLE
            ============================================================ */}
        <div className="finance-list">
          {paginatedClaims.length === 0 ? (
            <div className="empty-state">
              <i className="fas fa-inbox"></i>
              <p>No claims found matching your filters</p>
              <button className="btn-outline small" onClick={handleClearFilters}>
                Clear Filters
              </button>
            </div>
          ) : (
            <table className="finance-table">
              <thead>
                <tr>
                  <th onClick={() => handleSort('covernoteRefNumber')}>
                    Cover Note {sortField === 'covernoteRefNumber' && (sortDirection === 'asc' ? '↑' : '↓')}
                  </th>
                  <th onClick={() => handleSort('customerName')}>
                    Customer {sortField === 'customerName' && (sortDirection === 'asc' ? '↑' : '↓')}
                  </th>
                  <th onClick={() => handleSort('msisdn')}>
                    Phone {sortField === 'msisdn' && (sortDirection === 'asc' ? '↑' : '↓')}
                  </th>
                  <th>Type</th>
                  <th onClick={() => handleSort('status')}>
                    Status {sortField === 'status' && (sortDirection === 'asc' ? '↑' : '↓')}
                  </th>
                  <th onClick={() => handleSort('total_amount')}>
                    Amount {sortField === 'total_amount' && (sortDirection === 'asc' ? '↑' : '↓')}
                  </th>
                  <th>Transaction</th>
                  <th onClick={() => handleSort('created_at')}>
                    Date {sortField === 'created_at' && (sortDirection === 'asc' ? '↑' : '↓')}
                  </th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {paginatedClaims.map(claim => (
                  <tr key={claim.id} className={claim.status === CLAIM_STATUS.READY_VERIFY ? 'ready-row' : ''}>
                    <td className="claim-ref">{claim.covernoteRefNumber}</td>
                    <td>{claim.customerName}</td>
                    <td>{claim.msisdn}</td>
                    <td>{getTypeBadge(claim)}</td>
                    <td>{getStatusBadge(claim.status)}</td>
                    <td className="amount-cell">{formatCurrency(claim.total_amount)}</td>
                    <td>{claim.transaction_id || 'N/A'}</td>
                    <td>{formatDate(claim.created_at || claim.insuranceClaimDate)}</td>
                    <td>
                      <div className="row-actions">
                        {claim.screenshot && (
                          <button 
                            className="action-btn view"
                            onClick={() => handleViewScreenshot(claim)}
                            title="View Screenshot"
                          >
                            <i className="fas fa-image"></i>
                          </button>
                        )}
                        {claim.status === CLAIM_STATUS.READY_VERIFY && (
                          <>
                            <button 
                              className="action-btn verify"
                              onClick={() => handleVerify(claim.id)}
                              title="Verify"
                            >
                              <i className="fas fa-check"></i>
                            </button>
                            <button 
                              className="action-btn reject"
                              onClick={() => handleReject(claim.id)}
                              title="Reject"
                            >
                              <i className="fas fa-times"></i>
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
        
        {/* ============================================================
            PAGINATION
            ============================================================ */}
        {totalPages > 1 && (
          <div className="pagination">
            <button
              className="page-btn"
              onClick={() => handlePageChange(currentPage - 1)}
              disabled={currentPage === 1}
            >
              <i className="fas fa-chevron-left"></i>
            </button>
            {Array.from({ length: Math.min(totalPages, 5) }, (_, i) => {
              let pageNum;
              if (totalPages <= 5) {
                pageNum = i + 1;
              } else if (currentPage <= 3) {
                pageNum = i + 1;
              } else if (currentPage >= totalPages - 2) {
                pageNum = totalPages - 4 + i;
              } else {
                pageNum = currentPage - 2 + i;
              }
              return (
                <button
                  key={pageNum}
                  className={`page-btn ${currentPage === pageNum ? 'active' : ''}`}
                  onClick={() => handlePageChange(pageNum)}
                >
                  {pageNum}
                </button>
              );
            })}
            <button
              className="page-btn"
              onClick={() => handlePageChange(currentPage + 1)}
              disabled={currentPage === totalPages}
            >
              <i className="fas fa-chevron-right"></i>
            </button>
            <span className="page-info">
              Page {currentPage} of {totalPages}
            </span>
          </div>
        )}
      </div>
      
      {/* ============================================================
          SCREENSHOT MODAL
          ============================================================ */}
      {showScreenshotModal && selectedClaim && selectedClaim.screenshot && (
        <div className="modal-overlay" onClick={() => setShowScreenshotModal(false)}>
          <div className="modal-content screenshot-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Transaction Screenshot</h3>
              <button className="modal-close" onClick={() => setShowScreenshotModal(false)}>
                <i className="fas fa-times"></i>
              </button>
            </div>
            <div className="modal-body">
              <div className="screenshot-info">
                <p><strong>Claim:</strong> {selectedClaim.covernoteRefNumber}</p>
                <p><strong>Transaction ID:</strong> {selectedClaim.transaction_id}</p>
                <p><strong>Amount:</strong> {formatCurrency(selectedClaim.total_amount)}</p>
                <p><strong>Customer:</strong> {selectedClaim.customerName}</p>
                <p><strong>Date:</strong> {formatDate(selectedClaim.transaction_date)}</p>
              </div>
              <div className="screenshot-container">
                <img 
                  src={selectedClaim.screenshot} 
                  alt="Transaction Screenshot" 
                  className="screenshot-image"
                  onError={(e) => {
                    e.target.style.display = 'none';
                    e.target.parentElement.innerHTML = '<div class="no-screenshot"><i class="fas fa-image"></i><p>Screenshot not available</p></div>';
                  }}
                />
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn-outline" onClick={() => setShowScreenshotModal(false)}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* ============================================================
          BACKEND INTEGRATION GUIDE (Hidden)
          ============================================================ */}
      <div className="backend-guide" style={{ display: 'none' }}>
        {/*
          ============================================================
          BACKEND INTEGRATION GUIDE
          ============================================================
          
          API Endpoints Needed:
          
          1. GET /api/claims/finance
             Query params:
             - type: 'all' | 'replacement' | 'repair' | 'excess'
             - status: 'all' | 'PENDING' | 'READY_VERIFY' | 'VERIFIED' | 'REJECTED'
             - startDate: ISO date string
             - endDate: ISO date string
             - search: string
             - page: number
             - limit: number
             - sort: string
             - direction: 'asc' | 'desc'
             
             Response:
             {
               claims: [],
               total: number,
               page: number,
               totalPages: number
             }
          
          2. POST /api/claims/:id/verify
             Body: { verifiedBy: userId }
             Response: { success: true, claim: {} }
          
          3. POST /api/claims/:id/reject
             Body: { rejectedBy: userId, reason: string }
             Response: { success: true, claim: {} }
          
          4. GET /api/claims/latest?limit=10
             Response: { claims: [] }
          
          5. GET /api/claims/ready-verify
             Response: { claims: [] }
          
          6. POST /api/claims/export
             Body: { 
               filters: { type, status, startDate, endDate },
               format: 'csv'
             }
             Response: CSV file download
          
          ============================================================
          DATABASE SCHEMA REFERENCES
          ============================================================
          
          CREATE TABLE claims (
            claim_id INT PRIMARY KEY AUTO_INCREMENT,
            covernote_number VARCHAR(50) UNIQUE NOT NULL,
            msisdn VARCHAR(20) NOT NULL,
            customer_name VARCHAR(100) NOT NULL,
            imei_number VARCHAR(50),
            model VARCHAR(100),
            brand VARCHAR(50),
            claim_type ENUM('Replacement', 'Repair'),
            claim_subtype ENUM('Normal', 'Excess'),
            status ENUM('PENDING', 'READY_VERIFY', 'VERIFIED', 'REJECTED', 'AWAITING_CARE', 'AWAITING_REP', 'COMPLETED'),
            amount DECIMAL(15,2),
            total_amount DECIMAL(15,2),
            transaction_id VARCHAR(100),
            transaction_date DATE,
            screenshot_url VARCHAR(500),
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            representative_id INT,
            verified_by INT,
            verified_at TIMESTAMP
          );
          
          CREATE INDEX idx_status ON claims(status);
          CREATE INDEX idx_claim_type ON claims(claim_type);
          CREATE INDEX idx_created_at ON claims(created_at);
        */}
      </div>
    </div>
  );
};

export default Finance;
